-- +goose Up
-- Seed 347 Workday-hosted (myworkdayjobs.com) tenants.
--
-- Generated 2026-05-16. Workday boards are tenant-specific: every tenant
-- has its own (host, site) pair under https://<host>/<site>, and the
-- machine-readable jobs feed lives at https://<host>/wday/cxs/<tenant>/
-- <site>/jobs. Neither host nor site can be derived from companies.id
-- alone, so the Workday adapter reads them out of
-- company_scan_settings.adapter_config as `{"host": "...", "site": "..."}`.
-- This is the first adapter to require per-company adapter_config.
--
-- All 347 tenants are seeded with company_scan_settings.active=FALSE.
-- Admins must enable each tenant selectively via the admin UI; this
-- prevents the scheduler from immediately scheduling 347 new daily scans
-- against rate-limited Workday endpoints on first deploy. Combined with
-- the 15s inter_company_delay_s set in migration 054, the global crawler
-- stays well within Workday's per-tenant thresholds.
--
-- companies.careers_url and companies.website both point at the
-- user-facing board URL `https://<host>/<site>` (no `wday/cxs/` prefix)
-- so the values surface cleanly in the admin UI; the adapter never reads
-- these columns at scan time.
--
-- Collisions with previously seeded companies:
--   * `netflix` was already seeded in migration 038 pointing at the
--     Eightfold-hosted explore.jobs.netflix.net board. Netflix's Workday
--     tenant (netflix.wd1.myworkdayjobs.com/Netflix) is NOT seeded here —
--     the CXS endpoint returns HTTP 303 (the board has been retired),
--     so seeding it would only produce noise.
--
-- Schema notes (post-044):
--   companies              (id, name, slug, website, careers_url, logo_url)
--   company_scan_settings  (company_id, adapter_type, adapter_config, active)
--   Adapter type 'workday' is registered in adapter_configs via migration 054.

ON CONFLICT (id) DO UPDATE SET
    name        = EXCLUDED.name,
    slug        = EXCLUDED.slug,
    website     = EXCLUDED.website,
    careers_url = EXCLUDED.careers_url,
    logo_url    = COALESCE(EXCLUDED.logo_url, companies.logo_url),
    updated_at  = NOW();

ON CONFLICT (company_id) DO UPDATE SET
    adapter_type   = EXCLUDED.adapter_type,
    adapter_config = EXCLUDED.adapter_config,
    active         = EXCLUDED.active,
    updated_at     = NOW();

